/** Export authored cake half-turn models from committed, hash-locked Java 26.3 assets. */
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {createHash} from 'node:crypto';

/** Tracked resource root and exact source/generated byte inventories. */
const root=resolve(import.meta.dirname,'../../resources/minecraft/26.3'),inputs:Record<string,string>={},entries:{entry:string;size:number;sha256:string}[]=[];
/** Hash exact bytes for source attribution and runtime integrity.
 * @param {Uint8Array|string} bytes Resource bytes.
 * @return {string} SHA-256 digest.
 */
function hash(bytes:Uint8Array|string):string{return createHash('sha256').update(bytes).digest('hex');}
/** Read a committed original and record its provenance.
 * @param {string} path Pack-relative source.
 * @return {any} Parsed original JSON.
 */
function source(path:string):any{const bytes=readFileSync(resolve(root,path));inputs[path]=hash(bytes);return JSON.parse(bytes.toString());}
/** Emit one derived asset with its runtime size and hash.
 * @param {string} entry Pack-relative authored destination.
 * @param {unknown} value Derived JSON content.
 */
function emit(entry:string,value:unknown):void{const bytes=Buffer.from(JSON.stringify(value,null,2)+'\n');mkdirSync(dirname(resolve(root,entry)),{recursive:true});writeFileSync(resolve(root,entry),bytes);inputs[entry]=hash(bytes);entries.push({entry,size:bytes.length,sha256:hash(bytes)});}
/** All seven bite states retain their own complete inverted model. */
const variants:Record<string,{model:string}>={};
source('assets/minecraft/models/block/block.json');
for(const name of ['cake_top','cake_bottom','cake_side','cake_inner']){const path=`assets/minecraft/textures/block/${name}.png`;inputs[path]=hash(readFileSync(resolve(root,path)));}
for(let bites=0;bites<7;bites++){
    const model=source(`assets/minecraft/models/block/cake${bites?'_slice'+bites:''}.json`);
    model.parent='minecraft:block/block';
    for(const element of model.elements){element.rotation={origin:[8,4,8],axis:'x',angle:180};for(const face of Object.values(element.faces) as any[])delete face.cullface;}
    const id='jerrys_farm:block/ekac'+(bites?'_slice'+bites:'');
    emit('assets/jerrys_farm/models/'+id.split(':')[1]+'.json',model);variants['bites='+bites]={model:id};
}
emit('assets/jerrys_farm/blockstates/ekac.json',{variants});
/** Inventory, advancement and held items use the original generated item sprite, rotated around its center. */
const item=source('assets/minecraft/items/cake.json');
source('assets/minecraft/models/item/cake.json');
source('assets/minecraft/models/item/generated.json');
inputs['assets/minecraft/textures/item/cake.png']=hash(readFileSync(resolve(root,'assets/minecraft/textures/item/cake.png')));
item.model.transformation={translation:[1,1,0],left_rotation:[0,0,1,0]};
emit('assets/jerrys_farm/items/ekac.json',item);
writeFileSync(resolve(root,'easter-egg-manifest.json'),JSON.stringify({version:'26.3',clientSha1:'e877b6a07acd633fb3bb475002175cec036e7b87',source:'authored upside-down cake; original textures and all seven models rotated 180 degrees around [8,4,8]',exporterSha256:hash(readFileSync(import.meta.filename,'utf8').replaceAll('\r\n','\n')),inputs,entries,items:['jerrys_farm:ekac']},null,2)+'\n');
